  message: 'Too many requests from this IP, please try again later'
});
app.use(limiter);

// Request logging
app.use(morgan('combined', {
  skip: (req, res) => res.statusCode < 400
}));

// Logger configuration
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// User endpoint with sanitized data
app.get('/users', (req, res) => {
  // Sanitize email addresses by masking them
  res.json([
    { id: 1, name: 'Alice', email: 'alice@***redacted***' },
    { id: 2, name: 'Bob', email: 'bob@***redacted***' },
  ]);
});

// Example protected endpoint requiring API key
app.get('/api/protected', (req, res) => {
  const apiKey = req.headers['x-api-key'];

  if (!apiKey || apiKey !== process.env.API_KEY) {
    logger.warn('Unauthorized access attempt');
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Sanitize response
  res.json({ data: 'Sensitive data access granted', userData: { name: 'Current User' } });
});

// Input validation example
app.post('/api/create', [
  body('email').isEmail().normalizeEmail(),
  body('name').trim().escape()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation errors', { errors: errors.array() });
    return res.status(400).json({ errors: errors.array() });
  }

  res.json({ message: 'User created successfully', user: req.body });
});

// Error handling middleware
app.use((err, req, res, next) => {
  logger.error('Unhandled error', { error: err.message, stack: err.stack });
  res.status(500).json({ error: 'Internal server error' });
});

// 404 handler
app.use((req, res) => {
  logger.warn('404 Not Found', { path: req.path });
  res.status(404).json({ error: 'Resource not found' });
});

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  logger.info(`Secure server running on http://${HOST}:${PORT}`);
  console.log(`Secure server running on http://${HOST}:${PORT}`);
});

module.exports = app;

